# This is a backtracking visualiser, completely generated by AI based on my main.py.

import argparse, time

Q, ATK, FREE, DOT = "♛", "×", "·", "."


def bits(x, n):
    """Mask as a string, column 0 on the LEFT (matches the board)."""
    return format(x, f"0{n}b")[::-1]


def attacked(pos, r, c):
    return any(qc == c or abs(qr - r) == abs(qc - c) for qr, qc in enumerate(pos))


def render(n, pos, msg, st):
    cur = len(pos)
    out = ["      " + " ".join(str(c % 10) for c in range(n))]
    for r in range(n):
        if r < cur:   # placed rows: queen only
            cells = [Q if c == pos[r] else DOT for c in range(n)]
        else:         # open rows: what's attacked vs still safe
            cells = [ATK if attacked(pos, r, c) else FREE for c in range(n)]
        arrow = "→" if r == cur else " "
        out.append(f"  {arrow} {r:>2} " + " ".join(cells))
    out.append("")
    out.append(f"  step {st['steps']}  |  solutions {st['found']}/{st['m']}")
    out.append(f"  {msg}")
    return "\n".join(out)


def visualise(n, m, delay=0.4, step=False, clear=True):
    full = (1 << n) - 1
    pos = []
    st = {"found": 0, "steps": 0, "m": m}

    def show(msg):
        frame = render(n, pos, msg, st)
        if clear:
            print("\033[H\033[J", end="")
        print(frame, end="\n\n")
        if step:
            input("  [enter] next ")
        elif delay:
            time.sleep(delay)

    def go(cols, d1, d2):
        r = len(pos)
        if cols == full:
            st["found"] += 1
            show(f"✓ solution #{st['found']}: cols {[c + 1 for c in pos]}")
            return st["found"] == m             # stop once we hit the m-th

        free = full & ~(cols | d1 | d2)
        if not free:
            show(f"✗ row {r}: free={bits(free, n)} → no safe square, backtrack")
            return False

        while free:
            bit = free & -free
            c = bit.bit_length() - 1
            mask = free
            free ^= bit
            pos.append(c)
            st["steps"] += 1
            show(f"row {r}: free={bits(mask, n)} → place queen at col {c}")
            if go(cols | bit, ((d1 | bit) << 1) & full, (d2 | bit) >> 1):
                return True
            pos.pop()
            show(f"↩ row {r}: lift queen off col {c}")
        return False

    if not go(0, 0, 0):
        print(f"  only {st['found']} solution(s) exist for n={n}, no #{m}")


def main():
    p = argparse.ArgumentParser(description="Watch N-queens backtracking until the m-th solution.")
    p.add_argument("n", type=int, help="board size")
    p.add_argument("-m", type=int, default=1, help="stop at the m-th solution (default 1)")
    p.add_argument("--delay", type=float, default=0.4, help="seconds per frame (default 0.4)")
    p.add_argument("--step", action="store_true", help="press Enter for each frame")
    p.add_argument("--no-clear", dest="noClear", action="store_true", help="print frames one after another")
    a = p.parse_args()
    if a.n < 1 or a.m < 1:
        p.error("n and m must be >= 1")
    visualise(a.n, a.m, a.delay, a.step, not a.noClear)


if __name__ == "__main__":
    main()